62	/// Serializable error payload for crossing Temporal boundaries.
63	///
64	/// `AgentError` contains non-serializable variants (particularly `Other` with
65	/// `anyhow::Error`), so this type provides a wire-safe projection that can
66	/// be serialized and deserialized through Temporal activities.
67	#[derive(Debug, Clone, Serialize, Deserialize)]
68	pub enum ErrorKindPayload {
69	    /// Agent exhausted its turn budget before reaching a final output.
70	    MaxTurnsExceeded(u32),
71	    /// Structured output validation failed even after one repair attempt.
72	    InvalidStructuredOutput {
73	        /// Human-readable schema/validation errors.
74	        schema_errors: Vec<String>,
75	        /// The raw terminal assistant text that failed validation.
76	        final_text: String,
77	    },
78	    /// A downstream model call failed.
79	    Model {
80	        /// Error message from the model.
81	        message: String,
82	    },
83	    /// Handoff target is not supported (not yet used in Temporal workflow).
84	    HandoffUnsupported {
85	        /// The handoff target that was not supported.
86	        target: String,
87	    },
88	    /// Catch-all for all other agent errors.
89	    Other {
90	        /// Error message.
91	        message: String,
92	    },
93	}
94	
95	impl ErrorKindPayload {
96	    /// Lossy projection from [`paigasus_helikon_core::AgentError`].
97	    ///
98	    /// Converts the typed error surface into a serializable form for
99	    /// transmission through Temporal. Some variants (especially `Other` with
100	    /// `anyhow::Error`) degrade to string messages, as `anyhow::Error` is
101	    /// not `Serialize`.
102	    ///
103	    /// # Mapping
104	    ///
105	    /// - `MaxTurnsExceeded(n)` → `Self::MaxTurnsExceeded(n)`
106	    /// - `InvalidStructuredOutput { schema_errors, final_text }` → `Self::InvalidStructuredOutput { .. }`
107	    /// - `Model(e)` → `Self::Model { message: e.to_string() }`
108	    /// - Everything else (Tool, Session, Guardrail, HookDenied, etc.) → `Self::Other { message }`
109	    pub fn from_agent_error(e: &paigasus_helikon_core::AgentError) -> Self {
110	        match e {
111	            paigasus_helikon_core::AgentError::MaxTurnsExceeded(n) => Self::MaxTurnsExceeded(*n),
112	            paigasus_helikon_core::AgentError::InvalidStructuredOutput {
113	                schema_errors,
114	                final_text,
115	            } => Self::InvalidStructuredOutput {
116	                schema_errors: schema_errors.clone(),
117	                final_text: final_text.clone(),
118	            },
119	            paigasus_helikon_core::AgentError::Model(e) => Self::Model {
120	                message: e.to_string(),
121	            },
122	            _ => Self::Other {
123	                message: e.to_string(),
124	            },
125	        }
126	    }
127	
128	    /// Reconstruction into the typed error surface the Runner returns.
129	    ///
130	    /// Converts this serializable form back into an [`paigasus_helikon_core::AgentError`]
131	    /// for downstream error handling. Lossy variants (like `Other`) reconstruct
132	    /// with the stored message.
133	    pub fn into_agent_error(self) -> paigasus_helikon_core::AgentError {
134	        match self {
135	            Self::MaxTurnsExceeded(n) => paigasus_helikon_core::AgentError::MaxTurnsExceeded(n),
136	            Self::InvalidStructuredOutput {
137	                schema_errors,
138	                final_text,
139	            } => paigasus_helikon_core::AgentError::InvalidStructuredOutput {
140	                schema_errors,
141	                final_text,
142	            },
143	            Self::Model { message } => {
144	                paigasus_helikon_core::AgentError::Other(anyhow::anyhow!(message))
145	            }
146	            Self::HandoffUnsupported { target } => paigasus_helikon_core::AgentError::Other(
147	                anyhow::anyhow!("handoff unsupported: {}", target),
148	            ),
149	            Self::Other { message } => {
150	                paigasus_helikon_core::AgentError::Other(anyhow::anyhow!(message))
151	            }
152	        }
153	    }
154	}
